func run(ctx):
    var terrain = ctx.terrain(Vector2(100, 100), 6.0, 42, "Terrain")
    ctx.add_node("DirectionalLight3D", "Sun", null, {"rotation_degrees": Vector3(-45, 35, 0), "shadow_enabled": true, "light_energy": 1.2})
    ctx.ensure_environment()
    ctx.add_camera(Vector3(0, 45, 110), Vector3(0, 0, -10), true)
    var saved = ctx.save_scene()
    return {"saved": saved, "terrain": terrain != null}
